<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { getSystemUsers } from '../../api/modules/settings'; import type { SystemUser } from '../../types/settings'
const users=ref<SystemUser[]>([]),query=ref(''),role=ref('全部角色'),status=ref('全部状态'),editing=ref<SystemUser|null>(null)
const filtered=computed(()=>users.value.filter(u=>(!query.value||`${u.username}${u.name}`.toLowerCase().includes(query.value.toLowerCase()))&&(role.value==='全部角色'||u.role===role.value)&&(status.value==='全部状态'||u.status===status.value)))
onMounted(async()=>users.value=await getSystemUsers()); function create(){editing.value={username:'',name:'',role:'只读用户',status:'启用',lastLogin:'—',createdAt:'2026-08-19'}} function save(){if(!editing.value)return;const i=users.value.findIndex(u=>u.username===editing.value?.username);if(i<0)users.value.push({...editing.value});editing.value=null}
</script>
<template><section class="settings-page"><header class="settings-page__header"><div><p class="page-eyebrow">USER ADMINISTRATION</p><h1>用户管理</h1></div><button class="settings-primary" @click="create">＋ 新增用户</button></header><div class="settings-toolbar"><label><span>⌕</span><input v-model="query" placeholder="搜索用户名或姓名"></label><div><select v-model="role"><option>全部角色</option><option>现场人员</option><option>研发人员</option><option>只读用户</option></select><select v-model="status"><option>全部状态</option><option>启用</option><option>停用</option></select></div></div><div class="settings-table-wrap"><table class="settings-table"><thead><tr><th>用户名</th><th>姓名</th><th>角色</th><th>状态</th><th>最近登录</th><th>创建日期</th><th>操作</th></tr></thead><tbody><tr v-for="user in filtered" :key="user.username"><td class="type-data settings-id">{{user.username}}</td><td>{{user.name}}</td><td><span class="settings-tag" :class="user.role">{{user.role}}</span></td><td><span class="asset-status" :class="user.status==='启用'?'success':'neutral'">{{user.status}}</span></td><td class="muted-cell">{{user.lastLogin}}</td><td class="muted-cell">{{user.createdAt}}</td><td><button class="table-action" @click="editing={...user}">编辑</button></td></tr></tbody></table></div><div v-if="editing" class="modal-backdrop" @click.self="editing=null"><section class="settings-dialog"><header><div><small>USER PROFILE</small><strong>{{editing.username?'编辑用户':'新增用户'}}</strong></div><button @click="editing=null">×</button></header><div class="settings-dialog__body"><label>用户名<input v-model="editing.username" :readonly="users.some(u=>u.username===editing?.username)"></label><label>姓名<input v-model="editing.name"></label><label>角色<select v-model="editing.role"><option>现场人员</option><option>研发人员</option><option>只读用户</option></select></label><label>状态<select v-model="editing.status"><option>启用</option><option>停用</option></select></label></div><footer><button @click="editing=null">取消</button><button class="primary" :disabled="!editing.username||!editing.name" @click="save">保存用户</button></footer></section></div></section></template>
